sites.find:
while (result < 16) {
    if (entry->buffers[result] != 0) {
        entry->buffers[result]->GetStatus(&status);
        if ((status & DSBSTATUS_PLAYING) == 0) {
            goto play_voice;
        }
    }
    ++result;
}

replacements.text:
for (int index = 0; index < 16; ++index) {
    if (entry->buffers[index] != 0) {
        entry->buffers[index]->GetStatus(&status);
        if ((status & DSBSTATUS_PLAYING) == 0) {
            result = index;
            goto play_voice;
        }
    }
}
